const colorIs = (sel, x, y, hex) => { const p = pixel(sel, x, y); const n = parseInt(hex.slice(1), 16); return p[3] === 255 && p[0] === (n >> 16) && p[1] === ((n >> 8) & 255) && p[2] === (n & 255); };
const isEmpty = (sel, x, y) => pixel(sel, x, y)[3] === 0;
assert(colorIs("#banner", 5, 5, "#1b1f33") && colorIs("#banner", 295, 95, "#1b1f33"), "Afişin zemini #1b1f33 olmalı.");
assert(colorIs("#banner", 40, 50, "#f7df1e") && colorIs("#banner", 265, 30, "#4fc3f7") && colorIs("#banner", 215, 75, "#e53935"), "Her gezegen kendi renginde, merkezi (x, y) olan bir daire olmalı.");
