const canvas = document.querySelector("#chart");
const ctx = canvas.getContext("2d");
// Pazartesiden pazara çalışılan dakikalar
const minutes = [30, 45, 60, 20, 50, 10, 40];

function drawChart() {
  // temizle, çubukları çiz, toplamı yaz
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const max = Math.max(...minutes);
  ctx.fillStyle = "#4caf50";
  for (let i = 0; i < minutes.length; i++) {
    const h = minutes[i] / max * 100;
    ctx.fillRect(i * 40 + 5, canvas.height - h, 30, h);
  }
  const total = minutes.reduce((sum, m) => sum + m, 0);
  document.querySelector("#total").textContent = `Toplam: ${total} dk`;
}

drawChart();

check.js:
const colorIs = (sel, x, y, hex) => { const p = pixel(sel, x, y); const n = parseInt(hex.slice(1), 16); return p[3] === 255 && p[0] === (n >> 16) && p[1] === ((n >> 8) & 255) && p[2] === (n & 255); };
const isEmpty = (sel, x, y) => pixel(sel, x, y)[3] === 0;
assert(colorIs("#chart", 100, 30, "#4caf50"), "En uzun gün (60 dk) tam 100 piksel yüksekliğinde yeşil (#4caf50) bir çubuk olmalı.");
assert(isEmpty("#chart", 100, 10), "En uzun çubuk 100 pikselden uzun olmamalı.");
assert(colorIs("#chart", 220, 112, "#4caf50") && isEmpty("#chart", 220, 95), "Kısa günlerin çubukları orantılı olarak kısa olmalı (h = m / max * 100).");
assert(/Toplam:\s*255\s*dk/.test($("#total").textContent), "#total 'Toplam: 255 dk' yazmalı.");
minutes.length = 0;
minutes.push(120, 30, 90, 60, 0, 15, 45);
drawChart();
assert(colorIs("#chart", 20, 30, "#4caf50") && colorIs("#chart", 60, 110, "#4caf50"), "Veri değişince çubuklar yeni değerlere göre çizilmeli.");
assert(isEmpty("#chart", 60, 85) && isEmpty("#chart", 100, 30) && isEmpty("#chart", 180, 115), "drawChart() önce clearRect ile temizlemeli; ölçek yeni en büyük değere (max) göre hesaplanmalı.");
assert(/Toplam:\s*360\s*dk/.test($("#total").textContent), "Toplam, dizideki değerlerden hesaplanmalı.");

