project_task.solution:
const canvas = document.querySelector("#scores");
const ctx = canvas.getContext("2d");
const roundScores = [3, 5, 2, 4];

function drawScores() {
  // zemin, çubuklar, en iyi tur
  ctx.fillStyle = "#f3effa";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#7e57c2";
  let best = 0;
  for (let i = 0; i < roundScores.length; i++) {
    const h = roundScores[i] * 20;
    ctx.fillRect(10 + i * 50, canvas.height - h, 40, h);
    if (roundScores[i] > roundScores[best]) best = i;
  }
  document.querySelector("#best").textContent = `En iyi tur: ${best + 1} (${roundScores[best]} doğru)`;
}

drawScores();

check.js:
const colorIs = (sel, x, y, hex) => { const p = pixel(sel, x, y); const n = parseInt(hex.slice(1), 16); return p[3] === 255 && p[0] === (n >> 16) && p[1] === ((n >> 8) & 255) && p[2] === (n & 255); };
const isEmpty = (sel, x, y) => pixel(sel, x, y)[3] === 0;
assert(colorIs("#scores", 5, 5, "#f3effa"), "Zemin #f3effa ile boyanmalı.");
assert(colorIs("#scores", 30, 90, "#7e57c2") && colorIs("#scores", 30, 50, "#f3effa"), "1. tur (3 doğru) 60 piksel yüksekliğinde mor (#7e57c2) bir çubuk olmalı.");
assert(colorIs("#scores", 80, 30, "#7e57c2"), "2. tur (5 doğru) 100 piksel yüksekliğinde olmalı.");
assert($("#best").textContent.trim() === "En iyi tur: 2 (5 doğru)", "#best 'En iyi tur: 2 (5 doğru)' yazmalı.");
roundScores.length = 0;
roundScores.push(1, 4, 4, 0, 2);
drawScores();
assert(colorIs("#scores", 30, 90, "#f3effa") && colorIs("#scores", 30, 110, "#7e57c2"), "Veri değişince grafik baştan çizilmeli (önce zemini boya).");
assert(colorIs("#scores", 130, 50, "#7e57c2") && colorIs("#scores", 230, 100, "#7e57c2") && colorIs("#scores", 180, 115, "#f3effa"), "Her tur için bir çubuk çizilmeli: yükseklik = puan * 20.");
assert($("#best").textContent.trim() === "En iyi tur: 2 (4 doğru)", "En iyi tur dizideki değerlerden bulunmalı; eşitlikte ilk tur kazanır.");
